sys_generative_ai_custom_llm_transformer.request_transformer:
(function(inputs) {
    var promptData = inputs.prompt_data;
    var prompt = promptData.prompt || '';

    var typeMatch = prompt.match(/TYPE:(.*)/);
    var instructionsMatch = prompt.match(/INSTRUCTIONS:(.*)/);
    var stateMatch = prompt.match(/STATE:([\s\S]*)/);

    var questionType = typeMatch ? typeMatch[1].trim() : 'boolean';
    var instructions = instructionsMatch ? instructionsMatch[1].trim() : prompt;
    var state = stateMatch ? stateMatch[1].trim() : prompt;

    var systemPrompt = 'You are a calibrated decision engine. Given a governance question and the known facts (STATE), answer with a single JSON object only, no other text: {"answer": true or false, "probability": a number between 0 and 1 representing your calibrated confidence}. Question type: ' + questionType + '.';
    var userPrompt = 'INSTRUCTIONS: ' + instructions + '\nSTATE: ' + state;

    var body = {
        model: 'openai/gpt-4o-mini',
        messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: userPrompt }
        ]
    };

    var headers = {};

    return {
        body: body,
        headers: headers
    };
})(inputs);

sys_generative_ai_custom_llm_transformer.response_transformer:
(function(inputs) {
    var responseBody = JSON.parse(inputs.response_body);
    var content = '';
    try {
        content = responseBody.choices[0].message.content;
    } catch (e) {
        return ['(no answer returned)'];
    }

    var parsed = null;
    try {
        var jsonMatch = content.match(/\{[\s\S]*\}/);
        parsed = JSON.parse(jsonMatch ? jsonMatch[0] : content);
    } catch (e) {
        return [content];
    }

    var responseTexts = [];
    responseTexts.push('answer: ' + JSON.stringify(parsed.answer));
    responseTexts.push('probability: ' + JSON.stringify(parsed.probability));
    return responseTexts;
})(inputs);
